+/**
+ * The day book: a record of what went out of the store.
+ *
+ * Each line records one handing-over: what packet, how many seeds, what was
+ * left. The day book is written one line at a time, opened where nobody has
+ * opened it yet, and read back in the order it was written in.
+ */
+
+/** The name of the file that holds the day book, in the store's root. */
+export const DAYBOOK = "daybook.txt";
+
+/** One line of the day book, recording what went out and what was left. */
+export function noted(name: string, seeds: number, left: number): string {
+  return `${name}: ${seeds} out, ${left} left`;
+}
+
+/** The lines a day book's text holds, in order, with blank ones left out. */
+export function handedOut(text: string): string[] {
+  return text
+    .split("\n")
+    .map((line) => line.trim())
+    .filter((line) => line.length > 0);
+}
