+/**
+ * A correction to a weighing: when the same ticket is weighed again and a
+ * different figure is right.
+ *
+ * A correction goes on the tape after the weighing it puts right, against the
+ * same ticket. It holds the figures the weighing should have had, and nothing
+ * else — no haulier, because the ticket already says whose lorry it was.
+ *
+ * The tape has no way of saying that a figure was ever put right, and every
+ * reading off it is the first one, wrong or not — but the tape is read with
+ * the last word standing.
+ */
+
+import { Buffer } from "node:buffer";
+
+import { FRAME_BYTES, KIND_AT, TICKET_AT, GROSS_AT, TARE_AT, NOTHING_OF_THE_KIND } from "./frames.ts";
+
+/** The kind byte a correction's frame carries. */
+export const A_CORRECTION = 2;
+
+export class Correction {
+  readonly ticket: number;
+  readonly grossKg: number;
+  readonly tareKg: number;
+
+  constructor(ticket: number, grossKg: number, tareKg: number) {
+    this.ticket = ticket;
+    this.grossKg = grossKg;
+    this.tareKg = tareKg;
+  }
+
+  /** What the load comes to once it is allowed for. */
+  netKg(): number {
+    return this.grossKg - this.tareKg;
+  }
+}
+
+/** One correction as it goes on the tape. */
+export function correctionFrame(correction: Correction): Buffer {
+  const frame = Buffer.alloc(FRAME_BYTES);
+  frame.writeUInt8(A_CORRECTION, KIND_AT);
+  frame.writeUInt32BE(correction.ticket, TICKET_AT);
+  frame.writeUInt32BE(correction.grossKg, GROSS_AT);
+  frame.writeUInt32BE(correction.tareKg, TARE_AT);
+  return frame;
+}
+
+/** The correction a frame holds, or nothing where the frame is of another kind. */
+export function correctionIn(frame: Buffer): Correction | null {
+  if (frame.length !== FRAME_BYTES || frame.readUInt8(KIND_AT) !== A_CORRECTION) {
+    return NOTHING_OF_THE_KIND;
+  }
+  return new Correction(
+    frame.readUInt32BE(TICKET_AT),
+    frame.readUInt32BE(GROSS_AT),
+    frame.readUInt32BE(TARE_AT),
+  );
+}
